import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Dashboard() {
  const { auth } = useAuth();
  const { user } = auth;

  return (
    <div className="mt-8">
      <h1 className="text-2xl font-bold mb-2">Welcome, {user.name}</h1>
      <p className="text-gray-500 mb-6 capitalize">Role: {user.role}</p>
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
        {user.role === 'patient' && (
          <>
            <DashCard to="/doctors" label="Browse Doctors" color="bg-blue-100" />
            <DashCard to="/appointments" label="My Appointments" color="bg-green-100" />
            <DashCard to="/records" label="Medical Records" color="bg-yellow-100" />
          </>
        )}
        {user.role === 'doctor' && (
          <DashCard to="/appointments" label="My Appointments" color="bg-green-100" />
        )}
      </div>
    </div>
  );
}

function DashCard({ to, label, color }) {
  return (
    <Link to={to} className={`${color} rounded-lg p-6 text-center font-medium hover:opacity-80 transition`}>
      {label}
    </Link>
  );
}
